/* Leonida Trophy Compendium — dark sunset theme. Own design, no Rockstar assets. */
:root {
  --bg: #0d1322; --panel: #151d31; --panel2: #1a2338; --line: #2b3752;
  --text: #e9ebf2; --muted: #9aa5bb; --amber: #f5b942; --teal: #2dd4bf;
  --pink: #f472b6; --red: #f87171; --green: #4ade80;
  --plat: #7dd3fc; --gold: #f5b942; --silver: #cbd5e1; --bronze: #d08a4b;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); font-family: Georgia, 'Times New Roman', serif; font-size: 15px; line-height: 1.45; }
h1, h2, h3, .earned, .tabs button, .chip, .grade { font-family: 'Segoe UI', Arial, sans-serif; }
.top { display: flex; justify-content: space-between; gap: 24px; padding: 16px 20px 10px; border-bottom: 2px solid var(--amber); flex-wrap: wrap; }
h1 { margin: 0; font-size: 26px; letter-spacing: .5px; }
.subtitle { margin: 4px 0 0; color: var(--muted); font-size: 13px; }
.progressblock { text-align: right; min-width: 320px; }
.earned { font-size: 24px; font-weight: 800; color: var(--amber); }
.bar { height: 8px; background: var(--panel); border: 1px solid var(--line); border-radius: 4px; margin: 6px 0 8px; overflow: hidden; }
.barfill { height: 100%; background: var(--amber); width: 0%; }
